import React from "react";
import backgroundVideo from "./back.mp4";
import NavBar from "../../../Components/NavBar/NavBar";
import { useInView } from 'react-intersection-observer';

function Section1() {
  const { ref, inView } = useInView({
    triggerOnce: false, // Trigger the animation only once
    threshold: 0.9, // Trigger when 50% of the element is visible
  });
  return (
    <div className="relative w-full h-screen">
      <NavBar page={"Home"}/>
      {/* Background Video */}
      <video
        className="w-full h-full object-cover absolute top-0 left-0 z-[-1]"
        src={backgroundVideo}
        loop
        muted
        autoPlay
        ></video>

      {/* Overlay Content */}
      <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-20 z-[-1]">
        <h1 ref={ref} className={`text-center text-6xl text-white transition-all duration-1000 ease-out transform    ${
          inView ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'
        } }`}>
          Explore The Wonder Of Solar System
        </h1>
         
      </div>

      {/* Additional Content */}
      {/* <div className="relative z-10 ">
        <section className="p-10">
          <h2 className="text-4xl text-center">About the Solar System</h2>
          <p className="text-lg mt-4 text-center">
            Discover the amazing planets, stars, and mysteries of the solar system.
          </p>
        </section>

        <section className="p-10">
          <h2 className="text-4xl text-center">Planets</h2>
          <p className="text-lg mt-4 text-center">
            Learn about the eight planets orbiting the Sun and their unique characteristics.
          </p>
        </section>
      </div> */}
    </div>
  );
}

export default Section1;
